// Tunnel-Sog: zieht das Bild je Frame zur Mitte und dreht leicht -
// uebers Feedback entsteht der klassische Tunnel (Quelle davor noetig).
vec2 warp(vec2 uv)
{
    vec2 d = uv - 0.5;
    float winkel = 0.06 + 0.05 * bass;
    float s = sin(winkel);
    float c = cos(winkel);
    float sog = 0.97 - 0.04 * bass;
    return 0.5 + mat2(c, -s, s, c) * d * sog;
}
